{
  "initial_state": "arrival_and_relaxation",
  "states": [
    {
      "id": "arrival_and_relaxation",
      "description": "The person arrives home, adjusts climate, and retrieves a drink.",
      "rules": [
        {
          "trigger": "The air conditioner is off with an indoor temperature of 29°C.",
          "action": "Operate the air conditioner: turn on at 26°C."
        },
        {
          "trigger": "The refrigerator door has been open for 1 minute.",
          "action": "Operate the refrigerator: close door."
        }
      ],
      "next": [
        {
          "to": "laundry_handling",
          "on": "The washing machine cycle has finished."
        }
      ]
    },
    {
      "id": "laundry_handling",
      "description": "The person manages laundry transfer from washer to dryer.",
      "rules": [
        {
          "trigger": "The washing machine cycle has finished.",
          "action": "Take the laundry out of the washing machine and place it inside the dryer."
        },
        {
          "trigger": "The washing machine cycle has finished.",
          "action": "Operate the dryer: start."
        }
      ],
      "next": [
        {
          "to": "dinner_cleanup",
          "on": "The person opens the refrigerator door."
        }
      ]
    },
    {
      "id": "dinner_cleanup",
      "description": "The person consumes a beverage and cleans up the cup.",
      "rules": [
        {
          "trigger": "The person leaves the empty cup on the kitchen counter.",
          "action": "Put the cup from the kitchen counter into the dishwasher."
        },
        {
          "trigger": "The person leaves the empty cup on the kitchen counter.",
          "action": "Operate the dishwasher: close door."
        }
      ],
      "next": []
    }
  ]
}
